const LIB=Object.fromEntries(CAT.map(([id,name,group,reps,sets,art,steps,errors,gear,unit])=>[id,{id,name,group,reps,sets,art,steps,errors,gear,unit,rest:/press|row|squat|rdl|pulldown|hip-thrust/i.test(id)?120:90}]));
const PLANS={A:{name:'Full Body A',label:'Ngực · Lưng · Chân',ids:['chest-machine','lat-pulldown','leg-press','lateral-raise','leg-curl','plank']},B:{name:'Full Body B',label:'Ngực trên · Vai · Chân',ids:['incline-db','chest-row','goblet-squat','rdl','db-shoulder','calf']},C:{name:'Full Body C',label:'Vai · Ngực · Toàn thân',ids:['machine-shoulder','pec-deck','cable-row','leg-press','leg-curl','triceps']}};
let S,ui={tab:'home',planPick:null,progEx:'',progMetric:'weight',shootMode:'quick',shootForm:null,shootFilter:'same',editShootId:null,shootPics:[],removedPics:[],histEditId:null,modalType:'',failure:'',activePhotoUrls:[],photoToken:0,working:false};
const shotBlank=()=>({date:localDay(),n:'30',pts:'',out:'',dist:'25',gun:'Súng thuê',ammo:'.22',targetId:'personal10',note:'',seriesSize:5,series:{}});
function notify(msg,error=false){const el=$('#toast');el.textContent=msg;el.className=error?'error':'';el.style.display='block';clearTimeout(notify.t);notify.t=setTimeout(()=>el.style.display='none',4200)}
function fail(msg){ui.failure=String(msg);notify('Không lưu được: '+ui.failure,true);renderBanner()}
async function persist(added=[],removed=[]){try{await Storage.write(S,added,removed);ui.failure='';renderBanner();return true}catch(e){fail(e?.message||e);return false}}
function renderBanner(){const old=$('#app .notification');if(old)old.remove();if(ui.failure){const div=document.createElement('div');div.className='notification';div.textContent='⚠️ Chưa lưu được dữ liệu: '+ui.failure+'. Hãy xuất backup và kiểm tra bộ nhớ iPhone.';$('#app').prepend(div)}}
function componentTitle(title,subtitle=''){return `<div class="page-head"><div><div class="overline">GYM LOG <span class="version">V10.0</span></div><h1>${ehtml(title)}</h1>${subtitle?`<div class="sub mt8">${ehtml(subtitle)}</div>`:''}</div></div>`}
function b(action,label,cls='btn-small',extra=''){return `<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`}
function stat(label,val){return `<div class="stat"><strong>${ehtml(val)}</strong><span>${ehtml(label)}</span></div>`}
const workoutSort=()=>[...S.workouts].sort((a,b)=>String(a.date).localeCompare(String(b.date))||Number(a.startedAt||0)-Number(b.startedAt||0));
const shotSort=()=>[...S.shooting].sort((a,b)=>String(a.date).localeCompare(String(b.date))||String(a.id).localeCompare(String(b.id)));
function nextPlan(){const recent=[...workoutSort()].reverse().find(w=>['A','B','C'].includes(w.planId));return !recent?'A':{A:'B',B:'C',C:'A'}[recent.planId]}
const selectedPlan=()=>ui.planPick||nextPlan();
function fromCatalog(id){const p=LIB[id]||{id:'custom-'+Storage.uid(),name:'Bài tự tạo',group:'Tự chọn',reps:'8-12',sets:2,rest:90,unit:'kg',art:'push'};return {id:p.id,name:p.name,group:p.group,reps:p.reps,unit:p.unit||'kg',rest:p.rest||90,sets:Array.from({length:p.sets||2},()=>({w:'',r:'',d:false}))}}
function bestPrevious(exId,exName){const rows=[...workoutSort()].reverse();for(const w of rows){const ex=(w.exercises||[]).find(x=>x.id===exId||x.name===exName);if(ex){const ss=(ex.sets||[]).filter(x=>x.d&&Number(x.r)>0);if(ss.length)return ss}}return[]}
function recommendation(ex){const prev=bestPrevious(ex.id,ex.name),nums=String(ex.reps||'8-12').split('-').map(Number),hi=nums[1]||nums[0]||12;if(!prev.length)return 'Bắt đầu nhẹ, ưu tiên kỹ thuật và biên độ thoải mái.';
 const weights=prev.map(s=>Number(s.w)),same=weights.every(x=>x===weights[0]),done=prev.length>=ex.sets.length&&prev.every(s=>Number(s.r)>=hi);
 const last=prev.map(s=>`${fmt(s.w)}×${fmt(s.r)}`).join(' · ');
 if(done&&same&&weights[0]>0)return `Lần trước ${last}. Đã đạt mục tiêu reps: có thể thử tăng mức nhỏ nhất nếu kỹ thuật ổn.`;
 return `Lần trước ${last}. Giữ mức phù hợp và tăng reps dần tới ${hi}.`}
function weeklyStrip(){const today=new Date(),dow=(today.getDay()+6)%7,monday=new Date(today);monday.setDate(today.getDate()-dow);const days=['T2','T3','T4','T5','T6','T7','CN'];return `<div class="week">${days.map((d,i)=>{const dt=new Date(monday);dt.setDate(monday.getDate()+i);const iso=localDay(dt),hit=S.workouts.some(w=>w.date===iso);return `<div class="day">${d}<div class="dot ${hit?'done':''} ${iso===localDay()?'today':''}">${hit?'✓':dt.getDate()}</div></div>`}).join('')}</div>`}
function viewHome(){const key=selectedPlan(),plan=PLANS[key],last=[...workoutSort()].reverse()[0];const shown=(S.workouts.filter(w=>w.date>=weekStart())).length;return componentTitle('Hôm nay','Tập đều · Tăng cơ · Ghi nhanh')+`${S.draft?`<div class="card hero"><div class="overline">ĐANG TẬP DỞ</div><h2 class="mt8">${ehtml(S.draft.planName)}</h2><div class="sub mt8">${S.draft.exercises.length} bài · ${doneSets(S.draft)}/${totalSets(S.draft)} set hoàn thành</div>${b('resume','Tiếp tục buổi tập','btn-primary btn-wide mt16')}</div>`:''}<div class="card">${weeklyStrip()}<div class="card-row mt12"><span class="sub">Tuần này</span><b>${shown}/3 buổi</b></div></div><div class="card hero"><div class="overline">BUỔI TIẾP THEO</div><h2 class="mt8">${ehtml(plan.name)}</h2><div class="sub mt8">${ehtml(plan.label)} · ${plan.ids.length} bài · khoảng 60 phút</div><div class="plan-list">${['A','B','C'].map(k=>`<div class="plan-pill ${k===key?'current':''}">${k}</div>`).join('')}</div><div class="row mt16">${b('plan-choose','Đổi buổi','btn-ghost grow')}${b('start-workout','Bắt đầu tập','btn-primary grow',S.draft?'disabled':'')}</div></div><div class="card"><div class="card-row"><b>Chương trình hôm nay</b><span class="badge">${plan.ids.reduce((n,id)=>n+LIB[id].sets,0)} set</span></div>${plan.ids.map((id,i)=>`<div class="card-row mt12"><div><b>${i+1}. ${ehtml(LIB[id].name)}</b><div class="sub">${LIB[id].sets} × ${ehtml(LIB[id].reps)} · ${ehtml(LIB[id].group)}</div></div>${b('show-guide','ⓘ','btn-small btn-ghost',`data-ex="${ehtml(id)}"`)}</div>`).join('')}</div>${last?`<div class="card"><b>Lần tập gần nhất</b><div class="sub mt8">${humanDay(last.date)} · ${ehtml(last.planName)} · ${fmt(last.duration||0)} phút</div></div>`:''}<div class="hint">Tập 3 buổi/tuần theo thời gian rảnh. App xoay vòng A → B → C sau mỗi buổi hoàn thành, không ép ngày cố định.</div>`}
function weekStart(){const d=new Date(),k=(d.getDay()+6)%7;d.setDate(d.getDate()-k);return localDay(d)}
function totalSets(d){return(d.exercises||[]).reduce((a,x)=>a+(x.sets||[]).length,0)}
function doneSets(d){return(d.exercises||[]).reduce((a,x)=>a+(x.sets||[]).filter(z=>z.d).length,0)}
function viewWorkout(){const d=S.draft,pct=totalSets(d)?doneSets(d)*100/totalSets(d):0;return componentTitle(d.planName,'Buổi tập đang diễn ra')+`<div class="card"><div class="card-row"><div><span class="overline">THỜI GIAN</span><div class="metric" id="elapsed">${elapsed(d.startedAt)}</div></div>${b('cancel-workout','Hủy buổi','btn-danger')}</div><div class="card-row mt12"><span class="sub">Tiến độ</span><b>${doneSets(d)}/${totalSets(d)} set</b></div><div class="progress-bar mt8"><div style="width:${pct}%"></div></div><p class="sub mt8">Chỉ tick khi đã thực hiện và nhập đủ kg, reps. Tạ trước chỉ là gợi ý.</p></div>`+d.exercises.map((ex,i)=>{const prev=bestPrevious(ex.id,ex.name),guide=!!LIB[ex.id]||!!G[ex.name];return `<div class="card exercise"><div class="card-row"><div class="grow"><div class="ex-title">${ehtml(ex.name)}</div><div class="ex-meta">${ehtml(ex.group||'')} · ${ex.sets.length} × ${ehtml(ex.reps)} · ${ehtml(ex.unit||'kg')}</div></div>${guide?b('show-guide','ⓘ','btn-small btn-ghost',`data-ex="${ehtml(ex.id)}" data-ex-name="${ehtml(ex.name)}"`):''}</div><div class="small-note">${ehtml(recommendation(ex))}</div><div class="set-table header"><div>Set</div><div>${ehtml(ex.unit==='giây'?'Tạ / BW':'kg')}</div><div>${ex.unit==='giây'?'Giây':'Reps'}</div><div>✓</div></div>`+ex.sets.map((set,j)=>`<div class="set-table ${set.d?'complete':''} mt8"><div class="set-num">${j+1}</div><input type="number" min="0" max="1000" step="0.5" inputmode="decimal" data-set="w" data-i="${i}" data-j="${j}" aria-label="Khối lượng set ${j+1}" placeholder="${prev[j]?fmt(prev[j].w):'kg'}" value="${ehtml(set.w)}"><input type="number" min="1" max="1000" inputmode="numeric" data-set="r" data-i="${i}" data-j="${j}" aria-label="Lần hoặc giây set ${j+1}" placeholder="${prev[j]?fmt(prev[j].r):'reps'}" value="${ehtml(set.r)}"><button type="button" data-action="toggle-set" data-i="${i}" data-j="${j}" aria-label="${set.d?'Bỏ hoàn thành':'Hoàn thành'} set">✓</button></div>`).join('')+`<div class="row mt12">${b('add-set','+ Set','btn-small btn-ghost grow',`data-i="${i}"`)}${b('remove-set','− Set','btn-small btn-ghost',`data-i="${i}"`)}${b('swap-exercise','Đổi bài','btn-small',`data-i="${i}"`)}</div></div>`}).join('')+`<button type="button" class="btn-primary btn-wide" data-action="finish-workout">Hoàn thành buổi tập</button>`}
function elapsed(t){const secs=Math.max(0,Math.floor((Date.now()-Number(t||Date.now()))/1000));if(secs>86400)return 'Buổi cũ';return `${String(Math.floor(secs/60)).padStart(2,'0')}:${String(secs%60).padStart(2,'0')}`}
function duration(w){return Math.max(0,Number(w.duration)||0)}
function volume(w){return (w.exercises||[]).reduce((sum,ex)=>sum+(ex.sets||[]).filter(s=>s.d).reduce((a,set)=>a+(Number(set.w)||0)*(Number(set.r)||0),0),0)}
function viewHistory(){const all=[...workoutSort()].reverse(),month=localDay().slice(0,7),thisMo=all.filter(w=>w.date.startsWith(month));return componentTitle('Lịch sử','Mỗi buổi là một cột mốc')+`<div class="stats mb12">${stat('Buổi tháng này',thisMo.length)}${stat('Volume (kg×rep)',fmt(thisMo.reduce((a,w)=>a+volume(w),0)))}${stat('TB phút/buổi',thisMo.length?fmt(Math.round(thisMo.reduce((a,w)=>a+duration(w),0)/thisMo.length)):'—')}</div>${!all.length?'<div class="empty">Chưa có buổi tập nào được lưu.</div>':all.map(w=>`<details class="card history-item"><summary class="card-row"><div><b>${ehtml(w.planName||'Buổi tập')}</b><div class="sub">${humanDay(w.date)} · ${fmt(volume(w))} kg×rep · ${fmt(w.duration||0)} phút</div></div><span class="accent">⌄</span></summary><div class="history-more"><div class="separator"></div>${(w.exercises||[]).map(ex=>`<div class="history-ex"><b>${ehtml(ex.name)}</b><div>${(ex.sets||[]).filter(s=>s.d).map(s=>`<span class="history-set">${fmt(s.w)} × ${fmt(s.r)}</span>`).join('')||'<span class="muted">Không ghi set</span>'}</div></div>`).join('')}<div class="row mt12">${b('edit-history','Sửa buổi','btn-small btn-ghost grow',`data-id="${ehtml(w.id)}"`)}${b('delete-history','Xóa','btn-small btn-danger',`data-id="${ehtml(w.id)}"`)}</div></div></details>`).join('')}`}
function chart(points,unit=''){if(!points?.length)return '<div class="empty">Cần thêm dữ liệu để hiển thị biểu đồ.</div>';const arr=points.slice(-40),W=340,H=184,L=41,T=24,R=18,B=30,vals=arr.map(p=>Number(p.y)||0);let lo=Math.min(...vals),hi=Math.max(...vals);if(lo===hi){lo-=1;hi+=1}else{const pad=(hi-lo)*.17;lo-=pad;hi+=pad}const X=i=>L+(arr.length===1?.5:i/(arr.length-1))*(W-L-R),Y=v=>T+(hi-v)/(hi-lo)*(H-T-B),line=arr.map((p,i)=>`${X(i).toFixed(1)},${Y(p.y).toFixed(1)}`).join(' ');return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Biểu đồ ${ehtml(unit)}">${[0,.5,1].map(f=>{const v=lo+(hi-lo)*f,y=Y(v);return `<path d="M${L} ${y}H${W-R}" stroke="#2b3d54" stroke-width="1"/><text fill="#8b9db5" text-anchor="end" font-size="10" x="${L-7}" y="${y+4}">${fmt(v)}</text>`}).join('')}<polyline points="${line}" fill="none" stroke="#87a9ff" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${arr.map((p,i)=>`<circle cx="${X(i)}" cy="${Y(p.y)}" r="${i===arr.length-1?4:2.7}" fill="#a6baff"/>`).join('')}<text font-size="10" fill="#9daec6" x="${L}" y="${H-10}">${ehtml(humanDay(arr[0].date).slice(0,5))}</text><text font-size="10" fill="#9daec6" text-anchor="end" x="${W-R}" y="${H-10}">${ehtml(humanDay(arr.at(-1).date).slice(0,5))}</text></svg>`}
function progressSeries(){const m=new Map();for(const w of workoutSort())for(const ex of w.exercises||[]){const sets=(ex.sets||[]).filter(x=>x.d&&Number(x.r)>0);if(!sets.length)continue;const key=ex.id.startsWith('legacy-')?'legacy-name-'+ex.name:ex.id;if(!m.has(key))m.set(key,{name:ex.name,items:[]});m.get(key).items.push({date:w.date,sets})}return m}
function viewProgress(){const m=progressSeries(),keys=[...m.keys()];if(!keys.length)return componentTitle('Tiến bộ','Điều quan trọng là đều đặn')+'<div class="empty">Sau khi hoàn thành buổi tập đầu tiên, biểu đồ sẽ xuất hiện ở đây.</div>';if(!m.has(ui.progEx))ui.progEx=keys[0];const ex=m.get(ui.progEx),isTime=ex.items.every(x=>x.sets.every(s=>!Number(s.w))),metric=isTime?(ui.progMetric==='volume'?'reps':'reps'):ui.progMetric;
 const mapValue=arr=>{const ss=arr.sets;return metric==='weight'?Math.max(...ss.map(s=>Number(s.w))):metric==='est1rm'?Math.max(...ss.map(s=>Number(s.w)*(1+Math.min(Number(s.r),30)/30))):metric==='volume'?ss.reduce((t,s)=>t+Number(s.w)*Number(s.r),0):Math.max(...ss.map(s=>Number(s.r)))};const pts=ex.items.map(x=>({date:x.date,y:Math.round(mapValue(x)*10)/10}));const v=pts.at(-1)?.y,best=Math.max(...pts.map(p=>p.y));return componentTitle('Tiến bộ','Theo dõi từng bài, không chỉ mức tạ tối đa')+`<div class="card"><label class="label" for="prog-ex">Bài tập</label><select id="prog-ex">${keys.map(k=>`<option value="${ehtml(k)}" ${k===ui.progEx?'selected':''}>${ehtml(m.get(k).name)}</option>`).join('')}</select><div class="chips mt12">${[['weight',isTime?'Reps':'Mức tạ'],['reps','Reps'],['volume','Volume'],['est1rm','1RM ước tính']].filter(([id])=>!isTime||id==='reps'||id==='volume').map(([id,name])=>b('metric',name,'btn-small '+(metric===id?'selected':''),`data-metric="${id}"`)).join('')}</div><div class="card-row mt8"><div><div class="sub">Gần nhất</div><div class="metric">${fmt(v)}</div></div><div style="text-align:right"><div class="sub">Tốt nhất</div><h2>${fmt(best)}</h2></div></div>${chart(pts,metric)}<div class="sub">${pts.length} buổi được ghi nhận · 1RM chỉ là ước tính từ công thức Epley, không phải kết quả thử sức tối đa.</div></div><div class="hint">Tăng reps trước, tăng tạ từng bước nhỏ khi kỹ thuật và sự kiểm soát động tác vẫn tốt. Volume = kg × reps, chỉ mang tính tham khảo.</div>`}
const shotIdentity=x=>[x.targetId||'unknown',Number(x.dist)||'?',Number(x.n)||'?',String(x.gun||'').trim().toLowerCase()].join('|');
const shotMean=x=>x.n>0?Number(x.pts)/Number(x.n):0;
function selectedShots(){const all=shotSort();if(ui.shootFilter==='all')return all;const latest=[...all].reverse().find(x=>x.targetId==='personal10');if(!latest)return all;return all.filter(x=>shotIdentity(x)===shotIdentity(latest))}
function sourceShots(){return shotSort()}
function computeSeries(f){const n=Number(f.n),size=Number(f.seriesSize)||5;if(!Number.isInteger(n)||n<1||n>500)return[];if(![5,10].includes(size))return[];return Array.from({length:Math.ceil(n/size)},(_,i)=>({index:i,shots:Math.min(size,n-i*size),value:f.series?.[i]??''}))}
function shootForm(){const f=ui.shootForm||(ui.shootForm=shotBlank()),arr=computeSeries(f);const old=ui.editShootId?S.shooting.find(s=>s.id===ui.editShootId):null;const totalPts=arr.length&&arr.every(x=>x.value!==''&&Number.isFinite(dec(x.value)))?arr.reduce((n,x)=>n+dec(x.value),0):null;return `<div class="card"><div class="card-row"><div><b>${old?'Sửa buổi bắn':'Ghi buổi bắn'}</b><div class="sub">Pistole · 25m · .22 — có thể thay đổi</div></div>${old?b('shoot-reset','Hủy sửa','btn-small btn-ghost'):''}</div><div class="chips mt12">${b('shoot-mode','Nhập nhanh','btn-small '+(ui.shootMode==='quick'?'selected':''),`data-mode="quick"`)}${b('shoot-mode','Theo loạt','btn-small '+(ui.shootMode==='series'?'selected':''),`data-mode="series"`)}</div><div class="form-grid mt12">
${field('Ngày','date','date',f.date)}${field('Khoảng cách (m)','dist','number',f.dist,'min="1" max="1000" step="0.5"')}
${field('Số viên','n','number',f.n,'min="1" max="500" step="1"')}${field('Đạn','ammo','text',f.ammo,'maxlength="40"')}
<div class="form-field full"><label class="label" for="sf-gun">Súng sử dụng</label><input id="sf-gun" data-sf="gun" value="${ehtml(f.gun)}" placeholder="Súng thuê / model nếu biết" maxlength="60" list="known-guns"><datalist id="known-guns">${[...new Set(S.shooting.map(x=>x.gun).filter(Boolean))].map(x=>`<option value="${ehtml(x)}"></option>`).join('')}</datalist></div>
<div class="form-field full"><label class="label" for="sf-targetId">Loại bia / thang điểm</label><select id="sf-targetId" data-sf="targetId"><option value="personal10" ${f.targetId==='personal10'?'selected':''}>Bia 0–10 điểm/viên (tự khai báo)</option><option value="unknown" ${f.targetId==='unknown'?'selected':''}>Chưa xác định thang điểm</option></select></div>
${ui.shootMode==='quick'?field('Tổng điểm','pts','number',f.pts,'min="0" step="1" class="full"'):`<div class="full"><div class="card-row"><b>Điểm theo loạt</b><select id="sf-seriesSize" data-sf="seriesSize" style="width:118px"><option value="5" ${Number(f.seriesSize)===5?'selected':''}>5 viên</option><option value="10" ${Number(f.seriesSize)===10?'selected':''}>10 viên</option></select></div><div class="sub mt8">Tổng điểm tự cộng. Điểm tối đa mỗi viên: 10.</div>${arr.map(s=>`<div class="series-row"><div class="sub">Loạt ${s.index+1}<div class="tiny">${s.shots} viên</div></div><input type="number" min="0" max="${s.shots*10}" step="1" value="${ehtml(s.value)}" data-series="${s.index}" placeholder="0–${s.shots*10}" aria-label="Điểm loạt ${s.index+1}"><div class="sub">/${s.shots*10}</div></div>`).join('')||'<p class="warn">Nhập số viên hợp lệ để chia loạt.</p>'}<div class="card-row mt12"><span class="muted">Tổng điểm</span><b id="series-total">${totalPts===null?'Chưa đủ loạt':`${fmt(totalPts)} / ${fmt(Number(f.n)*10)}`}</b></div></div>`}
${field('Trượt / 0 điểm (không bắt buộc)','out','number',f.out,'min="0" max="500" step="1" class="full"')}
<div class="form-field full"><label class="label" for="sf-note">Ghi chú (không bắt buộc)</label><textarea id="sf-note" data-sf="note" placeholder="Cảm nhận buổi bắn, điều kiện bia…">${ehtml(f.note)}</textarea></div>
</div><div class="upload-zone mt12">${b('choose-photo','📷 Chụp / thêm ảnh bia','btn-ghost btn-wide')}<div class="sub mt8">Ảnh tự nén trước khi lưu offline, cạnh dài ≤ 1.600 px.</div><div id="pending-photos" class="photo-grid"></div></div><div class="row mt12">${b('save-shoot',old?'Lưu chỉnh sửa':'Lưu buổi bắn','btn-primary btn-wide')}</div></div>`}
function field(label,name,type,value,attrs=''){const id='sf-'+name;return `<div class="form-field"><label class="label" for="${id}">${label}</label><input id="${id}" data-sf="${name}" type="${type}" value="${ehtml(value)}" ${attrs}></div>`}
function viewShoot(){const all=sourceShots(),same=selectedShots(),record=same.filter(x=>x.n>0),N=record.reduce((a,x)=>a+Number(x.n),0),pts=record.reduce((a,x)=>a+Number(x.pts),0),miss=record.filter(x=>x.out!==null&&x.out!==undefined),missN=miss.reduce((a,x)=>a+Number(x.n),0),missed=miss.reduce((a,x)=>a+Number(x.out),0);const trend=record.map(x=>({date:x.date,y:Math.round(shotMean(x)*100)/100}));const best=record.length?record.reduce((a,x)=>shotMean(x)>shotMean(a)?x:a,record[0]):null;return componentTitle('Bắn súng','Shooting journal · Pistole 25m')+`<div class="stats mb12">${stat('Buổi',record.length)}${stat('Điểm TB/viên',N?(pts/N).toFixed(2):'—')}${stat('Trượt bia',missN?(missed/missN*100).toFixed(1)+'%':'—')}</div>${shootForm()}${all.length?`<div class="section"><h3>Tiến bộ</h3><span class="badge">${ui.shootFilter==='same'?'Cùng điều kiện':'Tất cả'}</span></div><div class="chips">${b('shoot-filter','Cùng điều kiện','btn-small '+(ui.shootFilter==='same'?'selected':''),`data-value="same"`)}${b('shoot-filter','Tất cả buổi','btn-small '+(ui.shootFilter==='all'?'selected':''),`data-value="all"`)}</div><div class="card"><div class="card-row"><div><div class="sub">Gần nhất</div><div class="metric">${record.length?shotMean(record.at(-1)).toFixed(2):'—'}</div></div><div><div class="sub">Điểm TB/viên tốt nhất</div><h2>${best?shotMean(best).toFixed(2):'—'}</h2></div></div>${chart(trend,'điểm / viên')}<div class="sub">${ui.shootFilter==='same'?'Chỉ so sánh cùng số viên, cự ly, bia và súng.':'Đang xem các điều kiện khác nhau; không dùng biểu đồ này để kết luận tiến bộ.'}</div></div><div class="section"><h3>Lịch sử bắn súng</h3><span class="sub">${all.length} buổi</span></div>${[...all].reverse().map(s=>`<div class="card"><div class="card-row"><div><b>${humanDay(s.date)}</b><div class="sub">${fmt(s.n)} viên · ${ehtml(s.dist?fmt(s.dist)+'m':'? m')} · ${ehtml(s.ammo||'Chưa rõ đạn')}</div></div><div style="text-align:right"><b>${fmt(s.pts)} điểm</b><div class="sub">${shotMean(s).toFixed(2)}/viên</div></div></div><div class="sub mt8">${ehtml(s.gun||'Chưa ghi súng')} · ${s.targetId==='personal10'?'Bia 0–10':'Bia chưa xác định'}${s.out!==null&&s.out!==undefined?` · Trượt ${fmt(s.out)}`:''}</div>${s.note?`<div class="sub mt8">${ehtml(s.note)}</div>`:''}${s.series?.length?`<div class="small-note">Loạt: ${s.series.map(x=>`${fmt(x.pts)}/${fmt(x.shots*10)}`).join(' · ')}</div>`:''}<div class="photo-grid" data-photo-grid="${ehtml(s.id)}"></div><div class="row">${b('edit-shoot','Sửa','btn-small btn-ghost grow',`data-id="${ehtml(s.id)}"`)}${b('delete-shoot','Xóa','btn-small btn-danger',`data-id="${ehtml(s.id)}"`)}</div></div>`).join('')}`:'<div class="empty">Chưa có buổi bắn. Bắt đầu với 25m · .22 và lưu lại một kết quả đầu tiên.</div>'}<div class="hint">Lưu ý: thang bia 0–10 đang là cấu hình cá nhân. Kết quả cũ v9 không được tự gán loại bia. Ảnh bia chỉ chụp khi trường bắn cho phép tiếp cận bia an toàn.</div>`}
function weightTrend(a){return a.map((x,i)=>{const from=x.date,begin=Date.parse(from)-6*864e5;const sample=a.filter(y=>Date.parse(y.date)>=begin&&Date.parse(y.date)<=Date.parse(from));return{date:from,y:Math.round(sample.reduce((n,y)=>n+y.kg,0)/sample.length*10)/10}})}
function viewWeight(){const a=[...S.weights].filter(x=>Number.isFinite(Number(x.kg))).sort((x,y)=>String(x.date).localeCompare(String(y.date)));const latest=a.at(-1),old=a[0];return componentTitle('Cân nặng','Xem xu hướng thay vì một ngày đơn lẻ')+`<div class="card"><div class="card-row"><div><div class="sub">Lần ghi gần nhất</div><div class="metric">${latest?fmt(latest.kg)+' kg':'—'}</div></div><div style="text-align:right"><div class="sub">Thay đổi từ đầu</div><b>${a.length>1?(latest.kg-old.kg>=0?'+':'')+(latest.kg-old.kg).toFixed(1)+' kg':'—'}</b></div></div>${chart(weightTrend(a),'kg trung bình 7 ngày')}<div class="sub">Đường biểu đồ là trung bình những lần cân trong 7 ngày gần nhất, không phải trung bình mỗi ngày nếu thiếu dữ liệu.</div><div class="row mt12"><input id="weight-new" type="number" min="20" max="500" step="0.1" inputmode="decimal" placeholder="Cân hôm nay (kg)" aria-label="Cân nặng hôm nay">${b('save-weight','Lưu','btn-primary')}</div></div>${[...a].reverse().slice(0,20).map(x=>`<div class="card-row" style="padding:8px 5px;border-bottom:1px solid var(--line)"><span class="sub">${humanDay(x.date)}</span><div><b>${fmt(x.kg)} kg</b> ${b('remove-weight','✕','btn-small btn-ghost',`data-id="${ehtml(x.id)}"`)}</div></div>`).join('')}<div class="section"><h3>Dữ liệu & Backup</h3></div><div class="card"><div class="sub">Dữ liệu và ảnh nằm trên iPhone, không nằm trên GitHub. Hãy lưu ZIP đầy đủ vào iCloud Drive định kỳ.</div><div class="grid2 mt12">${b('export-zip','↓ Backup ZIP + ảnh','btn-primary')}${b('export-json','↓ JSON không ảnh','btn-ghost')}</div><div class="row mt12">${b('import-backup','↑ Khôi phục / ghép backup','btn-ghost btn-wide')}</div><div class="sub mt12">Đã lưu ${fmt(S.workouts.length)} buổi gym · ${fmt(S.shooting.length)} buổi bắn · ${fmt(S.weights.length)} lần cân.</div><div class="sub mt8">Backup gần nhất: ${S.lastBackup?new Date(S.lastBackup).toLocaleString('vi-VN'):'Chưa có'}</div></div><div class="card"><b>Thông tin ứng dụng</b><div class="sub mt8">Gym Log v10.0 · PWA offline-first · Không cần tài khoản · Tự lưu vào IndexedDB.</div><div class="sub mt8">Source v9 không bị xóa. Nếu từng dùng bản v9 cùng tên miền và đường dẫn gốc, v10 sẽ tự chuyển dữ liệu từ localStorage.</div><div class="tiny mt12">Bản v10 không phải hướng dẫn y tế, huấn luyện thi đấu hay hệ thống lưu trữ đám mây.</div></div>`}
function refreshPhotoURLs(){for(const url of ui.activePhotoUrls)URL.revokeObjectURL(url);ui.activePhotoUrls=[]}
async function populatePhotoGrids(){const token=++ui.photoToken;const grids=$$('[data-photo-grid]');for(const g of grids){const item=S.shooting.find(x=>x.id===g.dataset.photoGrid),ids=(item?.photoIds||[]);if(!ids.length){g.remove();continue}const pics=await Storage.getPhotos(ids);if(ui.photoToken!==token)return;g.innerHTML=pics.filter(Boolean).map(p=>{const url=URL.createObjectURL(p.blob);ui.activePhotoUrls.push(url);return `<button type="button" class="photo-cell" style="padding:0" data-action="photo-view" data-id="${ehtml(p.id)}"><img src="${url}" loading="lazy" alt="Ảnh bia bắn"></button>`}).join('')}
 const pending=$('#pending-photos');if(pending){const old=ui.editShootId?S.shooting.find(x=>x.id===ui.editShootId):null;const keepIds=(old?.photoIds||[]).filter(id=>!ui.removedPics.includes(id));const keep=await Storage.getPhotos(keepIds);if(ui.photoToken!==token)return;pending.innerHTML=keep.filter(Boolean).map(p=>{const url=URL.createObjectURL(p.blob);ui.activePhotoUrls.push(url);return `<div class="photo-cell"><img src="${url}" alt="Ảnh cũ"><button type="button" data-action="remove-existing-photo" data-id="${ehtml(p.id)}">✕</button></div>`}).join('')+ui.shootPics.map((p,i)=>{const url=URL.createObjectURL(p.blob);ui.activePhotoUrls.push(url);return `<div class="photo-cell"><img src="${url}" alt="Ảnh mới"><button type="button" data-action="remove-pending-photo" data-index="${i}">✕</button></div>`}).join('');const dz=pending.closest('.upload-zone');if(dz){let badge=dz.querySelector('.thumb-count');if(!badge){badge=document.createElement('div');badge.className='thumb-count';dz.append(badge)}badge.textContent=ui.shootPics.length?`${ui.shootPics.length} ảnh mới đã nén (chưa lưu) · ${fmt(ui.shootPics.reduce((n,x)=>n+x.blob.size,0)/1024)} KB`:''}}}
function render(){refreshPhotoURLs();let html='';if(S.draft&&ui.tab==='home'&&ui.working)html=viewWorkout();else if(ui.tab==='home')html=viewHome();else if(ui.tab==='history')html=viewHistory();else if(ui.tab==='progress')html=viewProgress();else if(ui.tab==='shoot')html=viewShoot();else html=viewWeight();$('#app').innerHTML=html;$('#bottom-nav').innerHTML=NAV.map(([id,label,icon])=>`<button type="button" data-action="nav" data-to="${id}" ${ui.tab===id?'aria-current="page"':''}><span class="nav-icon">${I[icon]}</span><span>${label}</span></button>`).join('');renderBanner();drawTimer();if(ui.tab==='shoot')populatePhotoGrids().catch(e=>notify('Không mở được ảnh: '+e.message,true))}
function switchTab(id){ui.tab=id;ui.working=id==='home'&&!!S.draft;render();scrollTo({top:0,behavior:'instant'})}
function modal(html,type='generic'){ui.modalType=type;$('#modal-body').innerHTML=html;$('#modal').hidden=false;document.body.style.overflow='hidden'}
function closeModal(){$('#modal').hidden=true;$('#modal-body').innerHTML='';document.body.style.overflow='';ui.modalType=''}
function workoutSnapshot(){const s=S.draft;return{id:s.id,date:localDay(new Date(s.startedAt)),startedAt:s.startedAt,planId:s.planId,planName:s.planName,duration:clamp(Math.round((Date.now()-s.startedAt)/60000),1,600),exercises:s.exercises.map(x=>({...clone(x),sets:x.sets.filter(z=>z.d).map(z=>({...z,w:Number(z.w)||0,r:Number(z.r)||0,d:true}))}))}}
function startWorkout(key){if(S.draft){ui.working=true;ui.tab='home';render();return}if(!PLANS[key])return;S.draft={id:Storage.uid(),planId:key,planName:PLANS[key].name,startedAt:Date.now(),exercises:PLANS[key].ids.map(fromCatalog)};ui.planPick=null;ui.working=true;persist();render()}
function drawTimer(){const el=$('#rest-dock'),seconds=Math.max(0,Math.ceil((Number(S.timerUntil||0)-Date.now())/1000));if(!seconds){el.hidden=true;return}el.hidden=false;el.innerHTML=`<div><span class="tiny">NGHỈ GIỮA SET</span><div><strong>${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}</strong></div></div><div class="row">${b('timer-minus','−30','btn-small')}${b('timer-plus','+30','btn-small')}${b('timer-stop','Bỏ qua','btn-small btn-ghost')}</div>`}
function guideDiagram(kind='push'){const machine=kind==='pull'||kind==='row'||kind==='leg'?'<path d="M30 155V32H56 M210 155V32H188" stroke="#567295" stroke-width="5" fill="none"/>':'';
 const variants={push:'<path d="M104 94L68 85L58 52M136 94L174 85L184 52"/><path d="M51 52H66M175 52H191"/>',pull:'<path d="M105 92L82 66L67 42M135 92L158 66L173 42"/><path d="M60 40H180"/>',row:'<path d="M100 96L79 98L70 119M140 96L162 98L172 119"/><path d="M65 118H185"/>',raise:'<path d="M105 95L69 83L45 80M135 95L171 83L195 80"/><path d="M39 80h12M189 80h12"/>',curl:'<path d="M104 94L81 126L78 94M136 94L159 126L162 94"/><path d="M70 94h16M154 94h16"/>',squat:'<path d="M103 91L88 127L105 157M137 91L151 127L135 157"/><path d="M85 159h26M130 159h26"/><path d="M75 54H165"/>',hinge:'<path d="M95 89L80 128L100 158M125 89L153 118L164 158"/><path d="M65 110H180"/>',leg:'<path d="M104 95L83 127L70 126M138 95L156 127L181 126"/><path d="M62 126h17M179 126h12"/>',core:'<path d="M104 95L70 110L49 112M137 95L172 110L195 112"/><path d="M103 108L76 152M137 108L167 152"/>'};return `<div class="guide-art"><svg viewBox="0 0 240 185" role="img" aria-label="Sơ đồ tư thế minh họa, không phải video hướng dẫn động tác"><path d="M20 161H220" stroke="#3e5878" stroke-width="2"/>${machine}<circle cx="120" cy="47" r="19" fill="#9cbbff" opacity=".9"/><path d="M120 67L120 112" stroke="#b4d2ff" stroke-width="11" stroke-linecap="round"/><g fill="none" stroke="#85d9cb" stroke-width="7" stroke-linecap="round" stroke-linejoin="round">${variants[kind]||variants.push}</g><path d="M120 111L95 156M120 111L145 156" stroke="#9cbbff" stroke-width="8" stroke-linecap="round"/><circle cx="120" cy="48" r="2" fill="#27456d"/></svg></div>`}
function showGuide(id,name){const ex=LIB[id],legacy=!ex?G[name]:null;if(!ex&&!legacy){notify('Bài tự tạo chưa có hình hướng dẫn');return}const title=ex?.name||name;modal(`<div class="card-row"><h2>${ehtml(title)}</h2>${b('close-modal','✕','btn-small btn-ghost')}</div><div class="sub mt8">${ehtml(ex?.group||'Bài tập cũ')} · ${ehtml(ex?.gear||'')} · Sơ đồ tư thế minh họa</div>${guideDiagram(ex?.art||'push')}<div class="guide-tip"><strong>Cách thực hiện</strong><p class="mt8">${ehtml(ex?.steps||legacy?.[0])}</p></div><div class="guide-tip"><strong>Lỗi thường gặp</strong><p class="mt8">${ehtml(ex?.errors||legacy?.[1])}</p></div><div class="hint">Hình là sơ đồ gợi nhớ, không mô tả đủ toàn bộ biên độ chuyển động. Nếu chưa chắc kỹ thuật, hãy hỏi HLV tại phòng gym.</div><a class="btn-primary btn-wide mt12" style="display:flex;justify-content:center;align-items:center;border-radius:12px;text-decoration:none" target="_blank" rel="noopener noreferrer" href="https://www.youtube.com/results?search_query=${encodeURIComponent(title+' proper form exercise')}">Xem video động tác (cần mạng) ↗</a>`,'guide')}
function choosePlan(){const current=selectedPlan();modal(`<div class="card-row"><h2>Chọn buổi tập</h2>${b('close-modal','✕','btn-small btn-ghost')}</div><p class="sub mt8">Mặc định tiếp tục vòng A → B → C. Có thể chọn khác khi cần.</p>${Object.entries(PLANS).map(([k,p])=>`<button type="button" class="btn-wide mt12 ${k===current?'btn-primary':''}" style="text-align:left" data-action="select-plan" data-plan="${k}"><b>${ehtml(p.name)}</b><div class="small-note" style="color:inherit">${ehtml(p.label)} · ${p.ids.length} bài</div></button>`).join('')}`,'pick-plan')}
function chooseExercise(i){const old=S.draft?.exercises?.[i];if(!old)return;modal(`<div class="card-row"><h2>Đổi bài tập</h2>${b('close-modal','✕','btn-small btn-ghost')}</div><div class="sub mt8">Đang thay: ${ehtml(old.name)}. Set đã thực hiện sẽ bị đặt lại sau khi đổi bài.</div><label class="label mt12" for="exercise-search">Tìm bài</label><input id="exercise-search" placeholder="Gõ tên bài hoặc nhóm cơ" autocomplete="off"><div id="exercise-options" class="mt12">${exerciseList(i,'')}</div><div class="separator"></div><b>Tạo bài riêng</b><div class="grid2 mt12"><input id="custom-ex-name" maxlength="70" placeholder="Tên bài"><input id="custom-ex-reps" maxlength="12" placeholder="8-12" value="8-12"></div>${b('custom-exercise','Thêm bài riêng','btn-primary btn-wide mt12',`data-i="${i}"`)}`,'swap-'+i)}
function exerciseList(i,filter){const q=filter.toLowerCase();return CAT.filter(x=>(x[1]+' '+x[2]).toLowerCase().includes(q)).map(x=>`<button type="button" class="btn-wide mt8" data-action="replace-exercise" data-i="${i}" data-ex="${ehtml(x[0])}" style="text-align:left"><b>${ehtml(x[1])}</b><div class="sub">${ehtml(x[2])} · ${x[4]} × ${x[3]}</div></button>`).join('')||'<p class="sub">Không có bài tương ứng. Có thể tự thêm bên dưới.</p>'}
function editHistory(id){const w=S.workouts.find(x=>x.id===id);if(!w)return;ui.histEditId=id;modal(`<div class="card-row"><h2>Sửa buổi tập</h2>${b('close-modal','✕','btn-small btn-ghost')}</div><div class="grid2 mt12"><label class="form-field"><span class="label">Ngày</span><input id="hist-date" type="date" value="${ehtml(w.date)}"></label><label class="form-field"><span class="label">Phút tập</span><input id="hist-duration" type="number" min="1" max="600" value="${ehtml(w.duration||60)}"></label></div>${(w.exercises||[]).map((ex,i)=>`<div class="card mt12"><b>${ehtml(ex.name)}</b><div class="set-table header"><div>Set</div><div>kg</div><div>Reps</div><div></div></div>${(ex.sets||[]).map((s,j)=>`<div class="set-table mt8"><div class="set-num">${j+1}</div><input data-hw="w" data-i="${i}" data-j="${j}" type="number" min="0" max="1000" step="0.5" value="${ehtml(s.w)}"><input data-hw="r" data-i="${i}" data-j="${j}" type="number" min="1" max="1000" step="1" value="${ehtml(s.r)}"><span class="success">✓</span></div>`).join('')||'<div class="small-note">Không có set để sửa.</div>'}</div>`).join('')}${b('save-history-edit','Lưu thay đổi','btn-primary btn-wide mt12',`data-id="${ehtml(id)}"`)}`,'history-edit')}
function readNumber(raw,{integer=false,min=0,max=1000,empty=false}={}){if(raw===undefined||raw===null||String(raw).trim()==='')return empty?null:NaN;const n=dec(raw);return Number.isFinite(n)&&n>=min&&n<=max&&(!integer||Number.isInteger(n))?n:NaN}
function validateSet(set,unit='kg'){const bodyweight=['giây','lần'].includes(unit);return Number.isFinite(readNumber(set.r,{integer:true,min:1,max:1000}))&&(bodyweight?(set.w===''||set.w===null||Number.isFinite(readNumber(set.w,{min:0,max:1000}))):Number.isFinite(readNumber(set.w,{min:0,max:1000})))}
async function finishWorkout(){if(!S.draft||!doneSets(S.draft)){notify('Chưa hoàn thành set nào.',true);return}for(const ex of S.draft.exercises)for(const set of ex.sets.filter(x=>x.d))if(!validateSet(set,ex.unit)){notify('Có set đã tick nhưng kg/reps không hợp lệ.',true);return}const w=workoutSnapshot();if(w.duration>=180){const ask=prompt('Thời gian tính từ lúc bắt đầu khá dài. Nhập số phút tập thực tế (1–600):',String(w.duration));if(ask===null)return;const n=readNumber(ask,{integer:true,min:1,max:600});if(!Number.isFinite(n)){notify('Số phút không hợp lệ',true);return}w.duration=n}S.workouts.push(w);S.draft=null;S.timerUntil=0;if(!await persist()){S.workouts=S.workouts.filter(x=>x.id!==w.id);S.draft={id:w.id,planId:w.planId,planName:w.planName,startedAt:w.startedAt,exercises:clone(w.exercises)};return}ui.working=false;ui.tab='history';render();scrollTo(0,0);notify('Đã lưu buổi tập')}
async function compressPhoto(file){if(!file.type.startsWith('image/'))throw Error('Không phải file ảnh');if(file.size>40*1024*1024)throw Error('Ảnh gốc quá 40MB');const url=URL.createObjectURL(file),img=new Image();try{await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('Không đọc được ảnh HEIC/ảnh này'));img.src=url});const origW=img.naturalWidth,origH=img.naturalHeight;if(!origW||!origH)throw Error('Ảnh không hợp lệ');const scale=Math.min(1,1600/Math.max(origW,origH)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(origW*scale));c.height=Math.max(1,Math.round(origH*scale));const ctx=c.getContext('2d',{alpha:false});if(!ctx)throw Error('Trình duyệt không hỗ trợ nén ảnh');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,c.width,c.height);ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.drawImage(img,0,0,c.width,c.height);const toBlob=(t,q)=>new Promise(resolve=>c.toBlob(resolve,t,q));let blob=await toBlob('image/webp',.84);if(!blob||blob.type!=='image/webp')blob=await toBlob('image/jpeg',.84);if(!blob)throw Error('Không thể nén ảnh');if(blob.size>700*1024){const smaller=await toBlob(blob.type,.75);if(smaller&&smaller.size<blob.size)blob=smaller}return{blob,width:c.width,height:c.height,originalSize:file.size}}finally{URL.revokeObjectURL(url)}}
function totalSeries(){const f=ui.shootForm,arr=computeSeries(f);if(!arr.length||arr.some(x=>x.value===''))return null;let total=0;for(const s of arr){const val=readNumber(s.value,{integer:true,min:0,max:s.shots*10});if(!Number.isFinite(val))return null;total+=val}return total}
function populateShotForm(s){ui.editShootId=s?.id||null;ui.shootMode=s?.mode||'quick';ui.shootForm=s?{date:s.date,n:String(s.n),pts:String(s.pts),out:s.out===null||s.out===undefined?'':String(s.out),dist:String(s.dist??25),gun:s.gun||'',ammo:s.ammo||'',targetId:s.targetId||'unknown',note:s.note||'',seriesSize:s.series?.[0]?.shots===10?10:5,series:Object.fromEntries((s.series||[]).map((v,i)=>[i,String(v.pts)]))}:shotBlank();ui.shootPics=[];ui.removedPics=[]}
function validateShoot(){const f=ui.shootForm,n=readNumber(f.n,{integer:true,min:1,max:500}),dist=readNumber(f.dist,{min:1,max:1000}),out=readNumber(f.out,{integer:true,min:0,max:500,empty:true});const pts=ui.shootMode==='quick'?readNumber(f.pts,{integer:f.targetId==='personal10',min:0,max:5000}):totalSeries();if(!/^\d{4}-\d{2}-\d{2}$/.test(f.date)||!Number.isFinite(n)||!Number.isFinite(dist)||(!Number.isFinite(pts))||(f.out!==''&&(!Number.isFinite(out)||out>n)))return{error:'Kiểm tra ngày, số viên, tổng điểm, cự ly và số viên trượt.'};if(f.targetId==='personal10'&&pts>n*10)return{error:`Tối đa ${n*10} điểm với ${n} viên (thang 0–10).`};if(ui.shootMode==='series'&&(!computeSeries(f).length||computeSeries(f).some(x=>!Number.isFinite(readNumber(x.value,{integer:true,min:0,max:x.shots*10})))))return{error:'Mỗi loạt phải có điểm trong giới hạn hợp lệ.'};if(f.targetId==='personal10'&&out!==null&&out!==undefined&&pts>10*(n-out))return{error:'Tổng điểm vượt điểm tối đa khi đã trừ số viên 0 điểm.'};return{n,dist,out,pts}}
async function saveShoot(){if(!ui.shootForm||ui.workingSave)return;const val=validateShoot();if(val.error){notify(val.error,true);return}ui.workingSave=true;const f=ui.shootForm,old=ui.editShootId?S.shooting.find(x=>x.id===ui.editShootId):null;const id=old?.id||Storage.uid();const previous=old?clone(old):null;const arr=ui.shootMode==='series'?computeSeries(f).map(x=>({shots:x.shots,pts:dec(x.value)})):[];const photoIds=[...(old?.photoIds||[]).filter(x=>!ui.removedPics.includes(x)),...ui.shootPics.map(x=>x.id)];const next={id,date:f.date,n:val.n,pts:val.pts,out:val.out,dist:val.dist,gun:String(f.gun||'').trim().slice(0,60),ammo:String(f.ammo||'').trim().slice(0,40),note:String(f.note||'').trim().slice(0,2000),targetId:f.targetId,mode:ui.shootMode,series:arr,photoIds,...(old?.legacyOriginal?{legacyOriginal:old.legacyOriginal}:{})};if(old)S.shooting[S.shooting.findIndex(x=>x.id===id)]=next;else S.shooting.push(next);const ok=await persist(ui.shootPics.map(x=>({id:x.id,blob:x.blob})),ui.removedPics);ui.workingSave=false;if(!ok){if(old)S.shooting[S.shooting.findIndex(x=>x.id===id)]=previous;else S.shooting=S.shooting.filter(x=>x.id!==id);return}populateShotForm(null);ui.shootFilter='same';render();notify('Đã lưu buổi bắn và '+photoIds.length+' ảnh')}
async function openImage(id){const result=(await Storage.getPhotos([id]))[0];if(!result?.blob)return notify('Không tìm thấy ảnh',true);const url=URL.createObjectURL(result.blob);ui.modalImageUrl=url;modal(`<div class="card-row"><h2>Ảnh bia đã lưu</h2>${b('close-modal','✕','btn-small btn-ghost')}</div><div class="mt12" style="text-align:center"><img class="photo-preview" src="${url}" alt="Ảnh bia bắn"></div><div class="sub mt8">Đã nén · ${fmt(result.blob.size/1024)} KB</div>`,'photo-view')}
async function onAddPhoto(files){if(!ui.shootForm)ui.shootForm=shotBlank();if(!files?.length)return;try{notify('Đang xử lý '+files.length+' ảnh…');for(const f of files){const img=await compressPhoto(f);ui.shootPics.push({id:Storage.uid(),blob:img.blob});}render();notify(`Đã nén ${files.length} ảnh; bấm Lưu buổi bắn để lưu vào app.`)}catch(e){render();notify(e.message||'Không thể xử lý ảnh',true)}}
function prepareImport(){modal(`<div class="card-row"><h2>Nhập backup</h2>${b('close-modal','✕','btn-small btn-ghost')}</div><p class="sub mt12">Backup ZIP đầy đủ có ảnh; JSON không kèm ảnh. App hỗ trợ JSON v9 và JSON/ZIP v10.</p><div class="card mt12"><b>Ghép dữ liệu</b><p class="sub mt8">Giữ dữ liệu hiện tại, chỉ thêm bản ghi có ID chưa tồn tại. Ưu tiên dữ liệu hiện tại nếu trùng ID.</p></div><div class="card"><b>Thay thế toàn bộ</b><p class="sub mt8">Xuất backup an toàn trước, sau đó thay toàn bộ dữ liệu. Chỉ dùng khi muốn phục hồi máy mới.</p></div>${b('select-backup','Chọn file .json / .zip','btn-primary btn-wide')}`,'import-help')}
function previewImport(payload){ui.importPayload=payload;const d=payload.state;modal(`<div class="card-row"><h2>Xem trước bản sao lưu</h2>${b('close-modal','✕','btn-small btn-ghost')}</div><div class="stats mt12">${stat('Gym',d.workouts.length)}${stat('Bắn súng',d.shooting.length)}${stat('Ảnh',payload.photos.length)}</div><div class="sub mt12">Có ${d.weights.length} bản ghi cân nặng. Chưa thay đổi dữ liệu hiện tại.</div><div class="stack mt16"><label class="form-field"><span class="label">Cách khôi phục</span><select id="import-mode"><option value="merge">Ghép (không ghi đè ID trùng)</option><option value="replace">Thay thế toàn bộ (cần backup trước)</option></select></label>${b('apply-import','Tiến hành khôi phục','btn-primary btn-wide')}</div>`,'import-confirm')}
async function importApply(){const payload=ui.importPayload;if(!payload)return;const mode=$('#import-mode')?.value||'merge';if(!confirm(mode==='replace'?'Thao tác này THAY THẾ toàn bộ dữ liệu hiện tại. App sẽ xuất backup ZIP trước. Tiếp tục?':'Ghép dữ liệu từ file backup vào app?'))return;try{if(mode==='replace'){await Storage.exportFile(S,'zip');if(!confirm('Đã yêu cầu tải bản backup hiện tại. Hãy xác nhận lần nữa để thay thế.'))return}S=await Storage.replaceOrMerge(S,payload,mode);populateShotForm(null);closeModal();ui.tab='home';ui.working=!!S.draft;render();notify('Đã khôi phục dữ liệu thành công')}catch(e){notify('Khôi phục thất bại: '+(e.message||e),true)}}
async function act(button){const a=button.dataset.action;if(a==='close-modal'){if(ui.modalImageUrl){URL.revokeObjectURL(ui.modalImageUrl);ui.modalImageUrl=null}closeModal();return}
 if(a==='nav')return switchTab(button.dataset.to);
 if(a==='plan-choose')return choosePlan();
 if(a==='select-plan'){ui.planPick=button.dataset.plan;closeModal();render();return}
 if(a==='start-workout')return startWorkout(selectedPlan());
 if(a==='resume'){ui.working=true;render();return}
 if(a==='cancel-workout'){if(!confirm('Hủy buổi đang tập? Các set chưa lưu thành buổi sẽ bị mất.'))return;S.draft=null;S.timerUntil=0;if(await persist()){ui.working=false;render()}return}
 if(a==='toggle-set'){const i=Number(button.dataset.i),j=Number(button.dataset.j),ex=S.draft?.exercises?.[i],set=ex?.sets?.[j];if(!set)return;if(!set.d&&!validateSet(set,ex.unit)){notify('Nhập kg và reps thực tế trước khi tick ✓. Bài bodyweight có thể để kg trống.',true);return}set.d=!set.d;if(set.d){S.timerUntil=Date.now()+((ex.rest||90)*1000)}await persist();const pos=window.scrollY;render();window.scrollTo(0,pos);return}
 if(a==='add-set'||a==='remove-set'){const ex=S.draft?.exercises?.[Number(button.dataset.i)];if(!ex)return;if(a==='add-set')ex.sets.push({w:'',r:'',d:false});else{if(ex.sets.length<=1)return notify('Giữ ít nhất 1 set',true);if(ex.sets.at(-1).d&&!confirm('Set cuối đã hoàn thành, xóa set này?'))return;ex.sets.pop()}await persist();const pos=window.scrollY;render();scrollTo(0,pos);return}
 if(a==='show-guide')return showGuide(button.dataset.ex,button.dataset.exName);
 if(a==='swap-exercise')return chooseExercise(Number(button.dataset.i));
 if(a==='replace-exercise'||a==='custom-exercise'){const i=Number(button.dataset.i),current=S.draft?.exercises?.[i];if(!current)return;if(current.sets.some(s=>s.d)&&!confirm('Đổi bài sẽ xóa các set đã ghi ở bài này. Đồng ý?'))return;let item;if(a==='replace-exercise')item=fromCatalog(button.dataset.ex);else{const name=$('#custom-ex-name')?.value.trim(),reps=$('#custom-ex-reps')?.value.trim()||'8-12';if(!name||name.length>70||!/^\d{1,3}-\d{1,3}$/.test(reps))return notify('Tên bài hoặc khoảng reps không hợp lệ.',true);item={id:'custom-'+Storage.uid(),name,group:'Bài riêng',unit:'kg',reps,rest:90,sets:Array.from({length:2},()=>({w:'',r:'',d:false}))}}S.draft.exercises[i]=item;if(await persist()){closeModal();render()}return}
 if(a==='finish-workout')return finishWorkout();
 if(a==='edit-history')return editHistory(button.dataset.id);
 if(a==='delete-history'){if(!confirm('Xóa buổi tập này?'))return;const id=button.dataset.id,old=S.workouts;S.workouts=old.filter(x=>x.id!==id);if(!await persist())S.workouts=old;render();return}
 if(a==='save-history-edit'){const w=S.workouts.find(x=>x.id===button.dataset.id);if(!w)return;const date=$('#hist-date').value,minutes=readNumber($('#hist-duration').value,{integer:true,min:1,max:600});if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(minutes))return notify('Ngày hoặc số phút không hợp lệ.',true);const old=clone(w),sets=clone(w.exercises);for(const input of $$('[data-hw]')){const i=Number(input.dataset.i),j=Number(input.dataset.j),set=sets[i]?.sets?.[j];if(!set)continue;const value=readNumber(input.value,{integer:input.dataset.hw==='r',min:input.dataset.hw==='r'?1:0,max:1000});if(!Number.isFinite(value))return notify('Kiểm tra lại kg/reps trong lịch sử.',true);set[input.dataset.hw]=value}w.date=date;w.duration=minutes;w.exercises=sets;if(await persist()){closeModal();render();notify('Đã cập nhật lịch sử')}else Object.assign(w,old);return}
 if(a==='metric'){ui.progMetric=button.dataset.metric;render();return}
 if(a==='shoot-mode'){ui.shootMode=button.dataset.mode;render();return}
 if(a==='shoot-filter'){ui.shootFilter=button.dataset.value;render();return}
 if(a==='shoot-reset'){populateShotForm(null);render();return}
 if(a==='save-shoot')return saveShoot();
 if(a==='edit-shoot'){const s=S.shooting.find(x=>x.id===button.dataset.id);if(!s)return;populateShotForm(s);ui.tab='shoot';render();scrollTo(0,0);notify('Đang sửa buổi '+humanDay(s.date));return}
 if(a==='delete-shoot'){if(!confirm('Xóa buổi bắn này và các ảnh đã gắn?'))return;const id=button.dataset.id,old=S.shooting,sh=old.find(x=>x.id===id);S.shooting=old.filter(x=>x.id!==id);if(!await persist([],sh?.photoIds||[]))S.shooting=old;else if(ui.editShootId===id)populateShotForm(null);render();return}
 if(a==='choose-photo'){$('#photo-picker').click();return}
 if(a==='remove-pending-photo'){ui.shootPics.splice(Number(button.dataset.index),1);render();return}
 if(a==='remove-existing-photo'){if(!ui.removedPics.includes(button.dataset.id))ui.removedPics.push(button.dataset.id);render();return}
 if(a==='photo-view')return openImage(button.dataset.id);
 if(a==='save-weight'){const input=$('#weight-new'),n=readNumber(input?.value,{min:20,max:500});if(!Number.isFinite(n))return notify('Nhập cân nặng từ 20–500kg.',true);const old=clone(S.weights),date=localDay();S.weights=S.weights.filter(x=>x.date!==date);S.weights.push({id:Storage.uid(),date,kg:n});if(!await persist())S.weights=old;else notify('Đã lưu cân nặng');render();return}
 if(a==='remove-weight'){if(!confirm('Xóa lần cân này?'))return;const old=S.weights;S.weights=old.filter(x=>x.id!==button.dataset.id);if(!await persist())S.weights=old;render();return}
 if(a==='timer-plus'||a==='timer-minus'||a==='timer-stop'){if(a==='timer-stop')S.timerUntil=0;else S.timerUntil=Math.max(0,Number(S.timerUntil)+(a==='timer-plus'?30000:-30000));if(S.timerUntil<Date.now())S.timerUntil=0;await persist();drawTimer();return}
 if(a==='export-json'||a==='export-zip'){try{const type=a==='export-json'?'json':'zip';await Storage.exportFile(S,type);S.lastBackup=Date.now();await persist();render();notify(type==='zip'?'Đã yêu cầu tải backup ZIP có ảnh':'Đã yêu cầu tải JSON (không ảnh)')}catch(e){notify('Không xuất được backup: '+e.message,true)}return}
 if(a==='import-backup')return prepareImport();
 if(a==='select-backup'){$('#backup-picker').click();return}
 if(a==='apply-import')return importApply();
}
$('#app').addEventListener('input',event=>{const t=event.target;
 if(t.dataset.set&&S.draft){const ex=S.draft.exercises[Number(t.dataset.i)],s=ex?.sets?.[Number(t.dataset.j)];if(!s)return;s[t.dataset.set]=t.value;clearTimeout(ui.inputTimer);ui.inputTimer=setTimeout(()=>persist(),320);return}
 if(t.dataset.sf){ui.shootForm||(ui.shootForm=shotBlank());ui.shootForm[t.dataset.sf]=t.value;return}
 if(t.dataset.series!==undefined){ui.shootForm.series[Number(t.dataset.series)]=t.value;const total=totalSeries(),e=$('#series-total');if(e)e.textContent=total===null?'Chưa đủ loạt':fmt(total)+' / '+fmt(Number(ui.shootForm.n)*10);return}
 if(t.id==='exercise-search'){const i=Number(ui.modalType.split('-')[1]);const el=$('#exercise-options');if(el)el.innerHTML=exerciseList(i,t.value);return}
});
$('#app').addEventListener('change',event=>{const t=event.target;if(t.id==='prog-ex'){ui.progEx=t.value;render();return}if(t.dataset.sf&&['n','seriesSize','targetId'].includes(t.dataset.sf)){if(t.dataset.sf==='n'||t.dataset.sf==='seriesSize')ui.shootForm.series={};render()}});
document.addEventListener('click',event=>{const btn=event.target.closest('[data-action]');if(!btn||btn.disabled)return;act(btn).catch(err=>{console.error(err);notify(err?.message||'Có lỗi xảy ra',true)})});
$('#modal').addEventListener('click',event=>{if(event.target.dataset.action==='close-modal'&&ui.modalImageUrl){URL.revokeObjectURL(ui.modalImageUrl);ui.modalImageUrl=null}});
$('#photo-picker').addEventListener('change',event=>{onAddPhoto([...event.target.files]);event.target.value=''});
$('#backup-picker').addEventListener('change',async event=>{const file=event.target.files?.[0];event.target.value='';if(!file)return;try{const payload=await Storage.readImport(file);previewImport(payload)}catch(e){notify('Không mở được backup: '+(e.message||e),true)}});
async function boot(){try{S=await Storage.getState();Storage.validateState(S);if(S.migrationError)ui.failure='Không chuyển được toàn bộ dữ liệu v9. Bản cũ vẫn được giữ ở localStorage: '+S.migrationError;ui.working=!!S.draft;ui.shootForm=shotBlank();render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(e=>console.warn('Service Worker',e));setInterval(()=>{if(S?.draft&&ui.working){const el=$('#elapsed');if(el)el.textContent=elapsed(S.draft.startedAt)}if(S?.timerUntil){const left=S.timerUntil-Date.now();if(left<=0){S.timerUntil=0;persist();if(navigator.vibrate)navigator.vibrate(200)}drawTimer()}},1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)drawTimer()});}catch(e){console.error('Boot failed',e);$('#app').innerHTML=`<div class="notification">Không mở được dữ liệu của ứng dụng: ${ehtml(e?.message||e)}. Không xóa dữ liệu trình duyệt. Hãy kiểm tra quyền lưu trữ, dung lượng iPhone rồi tải lại trang.</div>`}}
boot();